$labels = ['accueil' => 'Mon tableau de bord', 'planning' => 'Mon planning', 'classes' => 'Mes classes', 'travaux' => $student ? 'Mes travaux' : 'Devoirs et rendus', 'resultats' => $student ? 'Mes résultats' : 'Notes et progression', 'ressources' => 'Mes ressources', 'presences' => 'Les présences', 'messages' => 'Les échanges', 'parcours' => 'Mon parcours', 'examens' => 'Examens et compétences', 'administration' => 'Administration', 'seance' => 'Ma séance'];
$nav = ['accueil' => '⌂', 'planning' => '▦', 'ressources' => '▤', 'travaux' => '✎', 'resultats' => '↗', 'presences' => '✓', 'messages' => '⋯', 'parcours' => '◇', 'examens' => '▣'];
if (!$student) { $nav = array_slice($nav, 0, 2, true) + ['classes' => '◎'] + array_slice($nav, 2, null, true); }
if ($admin) { $nav['administration'] = '⚙'; }
$fmt = static fn (?string $s, string $f = 'd/m/Y à H:i'): string => $s ? (new DateTimeImmutable($s, new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Indian/Reunion'))->format($f) : 'Non renseigné';
$name = static function (int $id) use ($state): string { foreach ($state['people'] as $person) { if ((int) $person['id'] === $id) return $person['name']; } return 'Membre de la promotion'; };
$cohortName = static function (int $id) use ($state): string { foreach ($state['cohorts'] as $c) { if ((int) $c['id'] === $id) return $c['name']; } return 'Promotion'; };
$sessionName = static function (int $id) use ($state): string { foreach ($state['sessions'] as $s) { if ((int) $s['id'] === $id) return $s['title']; } return 'Séance'; };
$assignmentName = static function (int $id) use ($state): string { foreach ($state['assignments'] as $a) { if ((int) $a['id'] === $id) return $a['title']; } return 'Devoir'; };
$students = array_values(array_filter($state['people'], static fn ($p) => $p['role'] === 'student'));
$trainers = array_values(array_filter($state['people'], static fn ($p) => $p['role'] === 'trainer'));
$begin = static function (string $action, string $return = '') use ($csrf, $page): void { ?><form method="post" action="<?= e(url('/espace-pedagogique/action/')) ?>" class="portal-form" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="return" value="<?= e($return ?: $page) ?>"><?php };
$end = static function (string $text = 'Enregistrer'): void { ?><button class="button button-dark" type="submit"><?= e($text) ?> →</button></form><?php };
$input = static function (string $key, string $label, string $type = 'text', string $value = '', bool $required = true): void { static $i = 0; $id = 'field-' . ++$i; ?><label for="<?= e($id) ?>"><?= e($label) ?></label><input id="<?= e($id) ?>" name="<?= e($key) ?>" type="<?= e($type) ?>" value="<?= e($value) ?>" <?= $required ? 'required' : '' ?> <?= $type === 'text' ? 'maxlength="180"' : '' ?>><?php };
$area = static function (string $key, string $label, string $value = ''): void { static $i = 0; $id = 'area-' . ++$i; ?><label for="<?= e($id) ?>"><?= e($label) ?></label><textarea id="<?= e($id) ?>" name="<?= e($key) ?>" rows="4" maxlength="10000" required><?= e($value) ?></textarea><?php };
$select = static function (string $key, string $label, array $options, string $valueKey = 'id', string $labelKey = 'name', bool $optional = false): void { static $i = 0; $id = 'select-' . ++$i; ?><label for="<?= e($id) ?>"><?= e($label) ?></label><select id="<?= e($id) ?>" name="<?= e($key) ?>" <?= $optional ? '' : 'required' ?>><option value=""><?= $optional ? 'Aucune séance associée' : 'Choisir…' ?></option><?php foreach ($options as $o): ?><option value="<?= e($o[$valueKey]) ?>"><?= e($o[$labelKey]) ?></option><?php endforeach; ?></select><?php };
$next = array_values(array_filter($state['sessions'], static fn ($s) => $s['ends_at'] > gmdate('Y-m-d H:i:s')));
$upcoming = $next[0] ?? null;
$statusLabels = ['declared' => 'Déclarée · à valider', 'validated' => 'Présence validée', 'late' => 'Retard', 'absent' => 'Absence', 'excused' => 'Absence justifiée'];
$futureAssignments = array_filter($state['assignments'], static fn ($a) => $a['due_at'] >= gmdate('Y-m-d H:i:s'));
?>
<div class="portal-shell"><aside class="portal-sidebar"><p class="portal-eyebrow">Mon espace</p><p class="portal-role"><?= e($roleLabel) ?></p><nav aria-label="Navigation pédagogique"><?php foreach ($nav as $key => $icon): ?><a href="<?= e(url('/espace-pedagogique/' . ($key === 'accueil' ? '' : $key . '/'))) ?>" <?= $page === $key || ($page === 'seance' && $key === 'planning') ? 'aria-current="page"' : '' ?>><span aria-hidden="true"><?= e($icon) ?></span><?= e($labels[$key]) ?></a><?php endforeach; ?></nav><div class="sidebar-help"><strong>Un besoin, une question ?</strong><p>L’équipe pédagogique vous accompagne.</p><a href="<?= e(url('/connexion/aide/')) ?>">Contacter l’administration ↗</a></div><a class="portal-back" href="<?= e(url('/')) ?>">← Retour au site Expernet</a></aside>
<main id="contenu" class="portal-content">
<div class="portal-breadcrumb">Espace pédagogique <span aria-hidden="true">/</span> <?= e($labels[$page]) ?></div>
