<div class="portal-heading"><div><p class="portal-eyebrow"><?= e($fmt(gmdate('Y-m-d H:i:s'), 'd/m/Y')) ?> · <?= e($roleLabel) ?></p><h1><?= $page === 'accueil' ? 'Bonjour, ' . e(explode(' ', $user['name'])[0]) . '<span class="hello-dot">.</span>' : e($labels[$page]) ?></h1><p><?= e(match($page) {'accueil' => 'Votre journée, vos cours et les prochaines étapes. Tout est ici.', 'planning' => 'Retrouvez vos séances et préparez votre prochaine intervention.', 'ressources' => 'Les documents utiles, rassemblés au même endroit.', 'travaux' => 'Des consignes au rendu, suivez chaque étape.', 'presences' => 'Un suivi clair pour chaque séance, en classe ou à distance.', 'resultats' => 'Consultez les résultats publiés et suivez la progression.', default => 'Les informations et les actions utiles à votre parcours.'}) ?></p></div><?php if ($page === 'accueil'): ?><a class="button button-dark" href="<?= e(url('/espace-pedagogique/planning/')) ?>">Voir mon planning ↗</a><?php endif; ?></div>
<?php if ($page === 'accueil'): ?>
<div class="portal-dashboard-grid"><section class="next-session"><div class="next-session-label"><span class="portal-eyebrow">Votre prochaine séance</span><span class="portal-pill"><?= $upcoming ? ($upcoming['mode'] === 'remote' ? 'À distance' : ($upcoming['mode'] === 'company' ? 'En entreprise' : 'En présentiel')) : 'À venir' ?></span></div><?php if ($upcoming): ?><div class="next-session-body"><div><p class="next-date"><?= e($fmt($upcoming['starts_at'], 'd/m')) ?><span><?= e($fmt($upcoming['starts_at'], 'H:i')) ?></span></p></div><div><p class="portal-eyebrow"><?= e($upcoming['cohort_name']) ?></p><h2><?= e($upcoming['title']) ?></h2><p><?= e($upcoming['trainer_name']) ?><br><?= e($upcoming['location']) ?> · jusqu’à <?= e($fmt($upcoming['ends_at'], 'H:i')) ?></p></div></div><a class="button button-orange" href="<?= e(url('/espace-pedagogique/seance/?id=' . $upcoming['id'])) ?>">Voir ma séance →</a><?php else: ?><h2>Votre planning est à jour.</h2><p>Aucune prochaine séance n’est programmée. Les nouvelles séances apparaîtront ici.</p><?php endif; ?></section>
<section class="portal-card quick-actions"><p class="portal-eyebrow">Pour avancer</p><h2>Vos accès directs</h2><a href="<?= e(url('/espace-pedagogique/travaux/')) ?>"><span>✎</span><div><strong><?= $student ? 'Mes travaux à rendre' : 'Devoirs et rendus' ?></strong><small><?= count($futureAssignments) ?> échéance(s) à venir</small></div><b>↗</b></a><a href="<?= e(url('/espace-pedagogique/ressources/')) ?>"><span>▤</span><div><strong>Mes ressources</strong><small><?= count($state['resources']) ?> document(s) disponible(s)</small></div><b>↗</b></a><a href="<?= e(url('/espace-pedagogique/presences/')) ?>"><span>✓</span><div><strong>Les présences</strong><small>Déclarations et suivi par séance</small></div><b>↗</b></a></section></div>
