<section class="portal-card"><div class="section-heading"><h2>À votre agenda</h2><a class="portal-link" href="<?= e(url('/espace-pedagogique/planning/')) ?>">Tout le planning →</a></div><?php foreach (array_slice($next, 0, 4) as $s): ?><a class="agenda-row" href="<?= e(url('/espace-pedagogique/seance/?id=' . $s['id'])) ?>"><span class="agenda-date"><?= e($fmt($s['starts_at'], 'd/m')) ?><small><?= e($fmt($s['starts_at'], 'H:i')) ?></small></span><div><strong><?= e($s['title']) ?></strong><p><?= e($s['cohort_name']) ?> · <?= e($s['trainer_name']) ?></p></div><span class="agenda-location"><?= e($s['location']) ?> ↗</span></a><?php endforeach; ?><?php if (!$next): ?><p class="portal-empty">Aucune séance à venir pour vos affectations actuelles.</p><?php endif; ?></section>
<?php elseif ($page === 'planning'): ?>
