<?php if ($trainer): ?><details class="portal-card"><summary>Créer un devoir</summary><?php $begin('assignments'); $select('cohort_id', 'Promotion', $state['cohorts']); $select('session_id', 'Séance associée (facultatif)', $state['sessions'], 'id', 'title', true); $input('title', 'Titre du devoir'); $area('description', 'Consignes'); $input('due_at', 'Date limite de rendu', 'datetime-local'); $end('Créer le devoir'); ?></details><?php endif; ?>
